import java.math.BigInteger
import java.util.*

const val MOD = 998244353
const val MAX = 5100 // s <= 5000, p <= 100

val fact = IntArray(MAX)
val invFact = IntArray(MAX)
val inv = IntArray(MAX)

fun modPow(a: Long, e: Long): Long {
    var res = 1L
    var base = a % MOD
    var exp = e
    while (exp > 0) {
        if (exp and 1L == 1L) res = res * base % MOD
        base = base * base % MOD
        exp = exp shr 1
    }
    return res
}

fun init() {
    fact[0] = 1
    for (i in 1 until MAX) fact[i] = (fact[i - 1].toLong() * i) % MOD
    invFact[MAX - 1] = modPow(fact[MAX - 1].toLong(), MOD - 2).toInt()
    for (i in MAX - 2 downTo 0) invFact[i] = (invFact[i + 1].toLong() * (i + 1)) % MOD
    inv[1] = 1
    for (i in 2 until MAX) inv[i] = (MOD - (MOD / i).toLong() * inv[MOD % i] % MOD).toInt()
}

fun C(n: Int, k: Int): Int {
    if (k < 0 || k > n) return 0
    return (fact[n].toLong() * invFact[k] % MOD * invFact[n - k] % MOD).toInt()
}

fun main() {
    init()
    val scanner = Scanner(System.`in`)
    val p = scanner.nextInt()
    val s = scanner.nextInt()
    val r = scanner.nextInt()

    // totalStates = number of ways to distribute s into p non-negative integers with a1 >= r
    // totalStates = C(s - r + p - 1, p - 1)
    val totalStates = C(s - r + p - 1, p - 1)

    var favorable = 0L

    // Hasan's score = x, where x >= r
    for (x in r..s) {
        val rem = s - x
        // remaining p-1 players sum to rem, each >= 0
        // We need to count ways where Hasan wins
        // Hasan wins if all other players have score <= x
        // If some have score == x, tie broken uniformly
        // Let k be the number of other players with score exactly x (0 <= k <= p-1)
        // Hasan's winning probability given k ties among others: 1 / (k + 1)
        // But we need to sum over all configurations
        // We can iterate k = number of other players with score == x
        // Choose k players out of p-1: C(p-1, k)
        // Remaining p-1-k players have score <= x-1, sum = rem - k*x
        // Let sumRest = rem - k*x. If sumRest < 0, skip.
        // Number of ways to distribute sumRest among p-1-k players with each <= x-1
        // This is stars and bars with upper bound: C(sumRest + (p-1-k) - 1, (p-1-k) - 1) minus those where some >= x
        // Inclusion-Exclusion:
        // ways = sum_{j=0}^{p-1-k} (-1)^j * C(p-1-k, j) * C(sumRest - j*x + (p-1-k) - 1, (p-1-k) - 1)
        // but only if sumRest - j*x >= 0
        // Actually, upper bound is x-1, so we subtract cases where at least one >= x.
        // Standard formula: number of non-negative solutions to y1+...+yn = S with yi <= U
        // = sum_{j=0}^n (-1)^j * C(n, j) * C(S - j*(U+1) + n - 1, n - 1)
        // Here n = p-1-k, U = x-1, so U+1 = x, S = sumRest.
        // So ways = sum_{j=0}^{p-1-k} (-1)^j * C(p-1-k, j) * C(sumRest - j*x + p-2-k, p-2-k)
        // provided sumRest - j*x >= 0.
        // Then total ways for this x and k = C(p-1, k) * ways.
        // Each such configuration contributes 1/(k+1) to winning probability.
        // So favorable += sum_{k} C(p-1, k) * ways * inv[k+1]
        for (k in 0..p-1) {
            val sumRest = rem - k * x
            if (sumRest < 0) continue
            val n = p - 1 - k
            var ways = 0L
            for (j in 0..n) {
                val curSum = sumRest - j * x
                if (curSum < 0) continue
                val term = C(n, j).toLong() * C(curSum + n - 1, n - 1) % MOD
                if (j % 2 == 0) {
                    ways = (ways + term) % MOD
                } else {
                    ways = (ways - term + MOD) % MOD
                }
            }
            val chooseK = C(p - 1, k).toLong()
            val probFactor = inv[k + 1].toLong()
            favorable = (favorable + chooseK * ways % MOD * probFactor) % MOD
        }
    }

    val ans = favorable * modPow(totalStates.toLong(), MOD - 2) % MOD
    println(ans)
}
